/*
 * Scenario authoring tool.
 *
 * Scenarios are DISCOVERED, not written — see src/engine/scenario.ts for why.
 * This searches seeds for a situation matching a brief ("player P8-P12 with
 * 12-15 laps left"), and prints the seed and lap that produce it. That pair is
 * the entire scenario definition; the situation itself is regenerated by the
 * engine at play time.
 *
 * Run:  npx vite-node scripts/find-scenarios.ts
 */
import { startScenario, describeSituation } from '../src/engine/scenario'
import { loadGameData } from '../src/data/validators'
import { buildScenarioConfig } from '../src/state/buildRaceConfig'
import type { RaceState } from '../src/engine/types'

const DATA = loadGameData()
const PLAYER = 'd_voss'

interface Brief {
  name: string
  circuitId: string
  /** Inspect each lap in this window for a match. */
  lapWindow: (totalLaps: number) => [number, number]
  match: (sit: NonNullable<ReturnType<typeof describeSituation>>, state: RaceState) => boolean
}

const BRIEFS: Brief[] = [
  {
    name: 'Recovery drive — buried in the pack, tyres to play with',
    circuitId: 'bengaluru',
    lapWindow: t => [Math.floor(t * 0.6), Math.floor(t * 0.8)],
    match: s => s.position >= 8 && s.position <= 12 && s.lapsRemaining >= 12 && s.lapsRemaining <= 16,
  },
  {
    name: 'Safety car gamble — the pit lane just got cheap',
    circuitId: 'veloce',
    lapWindow: t => [Math.floor(t * 0.3), Math.floor(t * 0.75)],
    match: s => s.safetyCarOut && s.position >= 4 && s.position <= 9 && s.lapsRemaining >= 10,
  },
  {
    name: 'Cliff edge — podium in hand, rubber gone',
    circuitId: 'harbour_lights',
    lapWindow: t => [Math.floor(t * 0.55), Math.floor(t * 0.85)],
    match: s => s.position >= 2 && s.position <= 4 && s.tyreAge >= 20 && s.lapsRemaining >= 8 && s.lapsRemaining <= 14,
  },
]

const SEEDS = Number(process.env.SEEDS ?? 400)

for (const brief of BRIEFS) {
  const circuit = DATA.circuits[brief.circuitId]!
  const [from, to] = brief.lapWindow(circuit.laps)
  const hits: string[] = []

  for (let seed = 1; seed <= SEEDS && hits.length < 3; seed++) {
    const config = buildScenarioConfig({ circuitId: brief.circuitId, seed, playerDriverId: PLAYER })
    for (let lap = from; lap <= to && hits.length < 3; lap++) {
      const { state } = startScenario(config, lap)
      const sit = describeSituation(state, PLAYER)
      if (!sit) break
      if (brief.match(sit, state)) {
        const gap = sit.gapAhead === null ? 'leading' : `+${sit.gapAhead.toFixed(1)}s`
        hits.push(
          `    seed ${String(seed).padStart(4)} startLap ${String(lap).padStart(2)}  ` +
          `P${sit.position} · ${sit.lapsRemaining} to go · ${sit.compound}${sit.tyreAge} · ${gap}` +
          (sit.safetyCarOut ? ' · SAFETY CAR' : ''),
        )
        break   // one hit per seed keeps the results varied
      }
    }
  }

  // eslint-disable-next-line no-console
  console.log(`\n${brief.name}\n  circuit ${brief.circuitId}, laps ${from}-${to}, searched ${SEEDS} seeds`)
  // eslint-disable-next-line no-console
  console.log(hits.length ? hits.join('\n') : '    (no match — widen the brief)')
}
